type UpdateRefundDisputeParams struct {
	RefundID       patch.Optional[uuid.UUID]
	AccountID      patch.Optional[uuid.UUID]
	Reason         patch.Optional[string]
	DateCreated    patch.Optional[time.Time]
	Status         patch.Optional[ordermodel.DisputeStatus]
	ResolvedByID   patch.Optional[uuid.NullUUID]
	DateResolved   patch.Optional[null.Time]
	ResolutionNote patch.Optional[null.String]
}

func (r *Repository) UpdateRefundDispute(ctx context.Context, id uuid.UUID, arg UpdateRefundDisputeParams) (uuid.UUID, error) {
	set := make([]string, 0, 8)
	args := pgx.NamedArgs{"id": id}
	if arg.RefundID.Set {
		set = append(set, `"refund_id" = @refund_id`)
		args["refund_id"] = arg.RefundID.Value
	}
	if arg.AccountID.Set {
		set = append(set, `"account_id" = @account_id`)
		args["account_id"] = arg.AccountID.Value
	}
	if arg.Reason.Set {
		set = append(set, `"reason" = @reason`)
		args["reason"] = arg.Reason.Value
	}
	if arg.DateCreated.Set {
		set = append(set, `"date_created" = @date_created`)
		args["date_created"] = arg.DateCreated.Value
	}
	if arg.Status.Set {
		set = append(set, `"status" = @status`)
		args["status"] = arg.Status.Value
	}
	if arg.ResolvedByID.Set {
		set = append(set, `"resolved_by_id" = @resolved_by_id`)
		args["resolved_by_id"] = arg.ResolvedByID.Value
	}
	if arg.DateResolved.Set {
		set = append(set, `"date_resolved" = @date_resolved`)
		args["date_resolved"] = arg.DateResolved.Value
	}
	if arg.ResolutionNote.Set {
		set = append(set, `"resolution_note" = @resolution_note`)
		args["resolution_note"] = arg.ResolutionNote.Value
	}
	if len(set) == 0 {
		return id, nil
	}
	sql := `UPDATE "order"."refund_dispute" SET ` + strings.Join(set, ", ") + ` WHERE "id" = @id RETURNING "id"`
	var pk uuid.UUID
	err := r.db.QueryRow(ctx, sql, args).Scan(&pk)
	return pk, err
}

func (r *Repository) DeleteRefundDispute(ctx context.Context, id uuid.UUID) error {
	_, err := r.db.Exec(ctx, `DELETE FROM "order"."refund_dispute" WHERE "id" = @id`, pgx.NamedArgs{"id": id})
	return err
}

